      "fact": "A vertical color scale legend is positioned to the right of the map, showing a gradient from dark maroon at the bottom to pale yellow at the top."
    }
  ],
  "printed_facts": [
    {
      "location": "Top left",
      "fact": "The title text reads 'Risk Index of Hazard H in US States'."
    },
    {
      "location": "Legend top",
      "fact": "The label 'High' is printed next to the number '100'."
    },
    {
      "location": "Legend bottom",
      "fact": "The label 'Low' is printed next to the number '0'."
    },
    {
      "location": "Legend axis",
      "fact": "Numerical ticks '80', '60', '40', and '20' are visible along the vertical scale."
    },
    {
      "location": "State labels",
      "fact": "Two-letter abbreviations such as 'AZ', 'ID', and 'SC' are printed within their respective state boundaries."
    }
  ],
  "public_definitions": [
    "Review the state risk dashboard, then open the state profile that should be routed into the highest-risk priority follow-up workflow.",
    "Use the state risk dashboard as the evidence source for the state priority profile routing decision."
  ],
  "uncertain": [
    "The specific numerical risk index value for each state is not explicitly printed on the map; values must be inferred from the color gradient.",
    "The exact meaning of the gray color is not defined in the legend, but it is distinct from the red-to-yellow risk scale."
  ]
